namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add spices and tomatoes, simmer 15 minutes.\n5. Stir in cream and add chicken.\n6. Simmer 10 more minutes. Serve with rice.", AverageRating = 4.7, RatingCount = 15 },
        new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nChili flakes", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Press and cube tofu, pan-fry until golden.\n3. Make sauce: tamarind, fish sauce, sugar, chili.\n4. Stir-fry noodles with sauce.\n5. Add tofu and bean sprouts.\n6. Garnish with peanuts, green onions, and lime.", AverageRating = 4.3, RatingCount = 8 },
        new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with meat and toppings.\n5. Serve with salsa and sour cream.", AverageRating = 4.2, RatingCount = 10 },
        new() { Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Preheat oven to 425°F.\n2. Melt chocolate and butter together.\n3. Whisk eggs, sugar, and vanilla.\n4. Fold in chocolate mixture and flour.\n5. Pour into greased ramekins.\n6. Bake 12-14 minutes until edges are set.\n7. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 25 },
        new() { Id = 7, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSesame oil\nSoft-boiled egg\nGreen onions\nNori\nCorn\nChashu pork", Steps = "1. Simmer broth with miso paste and soy sauce.\n2. Cook ramen noodles separately.\n3. Prepare soft-boiled eggs (6.5 minutes).\n4. Slice chashu pork.\n5. Assemble bowls: noodles, broth, toppings.\n6. Garnish with sesame oil and green onions.", AverageRating = 4.6, RatingCount = 18 },
        new() { Id = 8, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, jalapeño, and cilantro.\n4. Mix all ingredients together.\n5. Season with lime juice, salt, and garlic.\n6. Serve with tortilla chips.", AverageRating = 4.4, RatingCount = 14 },
    ];

    private static readonly List<RecipeCategory> Categories =
    [
        new() { Name = "Italian", Description = "Classic pasta, pizza, and Mediterranean flavors", Icon = "🍝" },
        new() { Name = "Indian", Description = "Rich curries, aromatic spices, and vibrant dishes", Icon = "🍛" },
        new() { Name = "Asian", Description = "Noodles, stir-fries, and umami-packed bowls", Icon = "🍜" },
        new() { Name = "Mexican", Description = "Bold flavors, fresh salsas, and street food favorites", Icon = "🌮" },
        new() { Name = "Desserts", Description = "Sweet treats, cakes, and indulgent delights", Icon = "🍰" },
    ];

    public List<RecipeCategory> GetCategories() => Categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
"}

