@page "/recipes/{Category}"
@using RecipeHub.Services
@using RecipeHub.Models

<PageTitle>@Category Recipes - RecipeHub</PageTitle>

<div class="container my-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@Category</li>
        </ol>
    </nav>

    <h2>@Category Recipes</h2>

    @if (Recipes.Count == 0)
    {
        <p class="text-muted">No recipes found in this category yet.</p>
    }
    else
    {
        <div class="row g-4 mt-2">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6">
                    <div class="card shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@using RecipeHub.Models

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

<div class="container my-4">
    @if (Recipe is null)
    {
        <p class="text-danger">Recipe not found.</p>
    }
    else
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/recipes/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            </ol>
        </nav>

        <h2>@Recipe.Title</h2>
        <p class="text-muted">⭐ @Recipe.AverageRating / 5 (@Recipe.RatingCount ratings)</p>

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n'))
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><strong>Instructions</strong></div>
                    <div class="card-body">
                        @foreach (var step in Recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="mt-4">
            <h5>Rate this recipe:</h5>
            <RecipeHub.Components.Shared.StarRating RecipeId="Recipe.Id" />
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
