@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Services
@using RecipeHub.Models
@using System.ComponentModel.DataAnnotations

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<div class="container my-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h2>📝 Submit a Recipe</h2>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <strong>Recipe submitted!</strong> Your recipe has been added to the community.
            <a href="/">Browse recipes</a>
        </div>
    }
    else
    {
        <EditForm Model="FormModel" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="FormModel.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => FormModel.Title" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="FormModel.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => FormModel.Category" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="FormModel.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
                <ValidationMessage For="() => FormModel.Ingredients" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="FormModel.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
                <ValidationMessage For="() => FormModel.Steps" />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private SubmitModel FormModel { get; set; } = new();
    private bool SubmitSuccess { get; set; }

    private void HandleSubmit()
    {
        RecipeService.SubmitRecipe(new RecipeSubmission
        {
            Title = FormModel.Title,
            Category = FormModel.Category,
            Ingredients = FormModel.Ingredients,
            Steps = FormModel.Steps
        });
        SubmitSuccess = true;
    }

    private class SubmitModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, MinimumLength = 3)]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please describe the preparation steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}
